import com.liferay.jenkins.results.parser.JenkinsResultsParserUtil;
import java.util.Properties;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public static File getBndFile(File file) {
	if (file == null) {
		return null;
	}

	File canonicalFile = JenkinsResultsParserUtil.getCanonicalFile(file);

	File parentFile = canonicalFile.getParentFile();

	if ((parentFile == null) || !parentFile.exists()) {
		return file;
	}

	if (!canonicalFile.isDirectory()) {
		return getBndFile(parentFile);
	}

	File testPropertiesFile = new File(canonicalFile, "bnd.bnd");

	if (!testPropertiesFile.exists()) {
		return getBndFile(parentFile);
	}

	return testPropertiesFile;
}

public static String getProjectName(File bndFile){
	Properties properties = JenkinsResultsParserUtil.getProperties(new File[] {bndFile});

	String bundleSymbolicName = properties.getProperty("Bundle-SymbolicName");

	System.out.println(bundleSymbolicName);

	String projectDir = project.getProperty("project.dir");
	System.out.println("PROJECT DIR : " + projectDir);
	File modulesPropertyFile = new File(projectDir + "/modules/modules.properties");
	System.out.println("MODULES PROPERTY FILE : " + modulesPropertyFile);
	Properties properties2 = JenkinsResultsParserUtil.getProperties(new File[] {modulesPropertyFile});

	return properties2.getProperty("project.name[" + bundleSymbolicName + "]");

}

public static String getTestName(String filePath){
	Pattern pattern = Pattern.compile(
			"/(\\w+)\\.java");

	Matcher matcher = pattern.matcher(filePath);

	String testName = "";
	if (matcher.find()) {
		testName = matcher.group(1);
		System.out.println(testName);
	}

	return testName;
}

String filePath = project.getProperty("filePath");
String testName = getTestName(filePath);
System.out.println("TEST NAME : " + testName);
project.setProperty("test.name", testName);

System.out.println("FILE PATH :  " + filePath);
File file = new File(filePath);
System.out.println("file : " + file);	
File bndFile = getBndFile(file);
System.out.println("BND FILE : " + bndFile);


String projectName = getProjectName(bndFile);
System.out.println("PROJECT NAME : " + projectName);

project.setProperty("project.name", projectName);


